"use client";

import { useId, useMemo, useState } from "react";

import { Button } from "@/components/ui/button";
import {
	Command,
	CommandEmpty,
	CommandGroup,
	CommandInput,
	CommandItem,
	CommandList,
} from "@/components/ui/command";
import { Label } from "@/components/ui/label";
import {
	Popover,
	PopoverContent,
	PopoverTrigger,
} from "@/components/ui/popover";
import { CheckIcon, ChevronDownIcon } from "lucide-react";

import { cn } from "../utilities/cn";

export default function Component() {
	const id = useId();
	const [open, setOpen] = useState<boolean>(false);
	const [value, setValue] = useState<string>("Europe/London");

	const timezones = Intl.supportedValuesOf("timeZone");

	const formattedTimezones = useMemo(() => {
		return timezones
			.map((timezone) => {
				const formatter = new Intl.DateTimeFormat("en", {
					timeZone: timezone,
					timeZoneName: "shortOffset",
				});
				const parts = formatter.formatToParts(new Date());
				const offset =
					parts.find((part) => part.type === "timeZoneName")?.value || "";
				const modifiedOffset = offset === "GMT" ? "GMT+0" : offset;

				return {
					value: timezone,
					label: `(${modifiedOffset}) ${timezone.replace(/_/g, " ")}`,
					numericOffset: parseInt(
						offset.replace("GMT", "").replace("+", "") || "0"
					),
				};
			})
			.sort((a, b) => a.numericOffset - b.numericOffset);
	}, [timezones]);

	return (
		<div className="*:not-first:mt-2">
			<Label htmlFor={id}>Timezone select with search</Label>
			<Popover open={open} onOpenChange={setOpen}>
				<PopoverTrigger asChild>
					<Button
						id={id}
						variant="outline"
						role="combobox"
						aria-expanded={open}
						className="bg-background hover:bg-background border-input w-full justify-between px-3 font-normal outline-offset-0 outline-none focus-visible:outline-[3px]"
					>
						<span
							className={cn(
								"truncate",
								!value && "text-muted-foreground"
							)}
						>
							{value
								? formattedTimezones.find(
										(timezone) => timezone.value === value
									)?.label
								: "Select timezone"}
						</span>
						<ChevronDownIcon
							size={16}
							className="text-muted-foreground/80 shrink-0"
							aria-hidden="true"
						/>
					</Button>
				</PopoverTrigger>
				<PopoverContent
					className="border-input w-full min-w-[var(--radix-popper-anchor-width)] p-0"
					align="start"
				>
					<Command
						filter={(value, search) => {
							const normalizedValue = value.toLowerCase();
							const normalizedSearch = search
								.toLowerCase()
								.replace(/\s+/g, "");
							return normalizedValue.includes(normalizedSearch) ? 1 : 0;
						}}
					>
						<CommandInput placeholder="Search timezone..." />
						<CommandList>
							<CommandEmpty>No timezone found.</CommandEmpty>
							<CommandGroup>
								{formattedTimezones.map(
									({ value: itemValue, label }) => (
										<CommandItem
											key={itemValue}
											value={itemValue}
											onSelect={(currentValue) => {
												setValue(
													currentValue === value
														? ""
														: currentValue
												);
												setOpen(false);
											}}
										>
											{label}
											{value === itemValue && (
												<CheckIcon size={16} className="ml-auto" />
											)}
										</CommandItem>
									)
								)}
							</CommandGroup>
						</CommandList>
					</Command>
				</PopoverContent>
			</Popover>
		</div>
	);
}

import * as React from "react";

import { cn } from "@/registry/utilities/cn";
import { Slot } from "@radix-ui/react-slot";
import { cva, type VariantProps } from "class-variance-authority";

const buttonVariants = cva(
	"inline-flex items-center justify-center whitespace-nowrap rounded-md text-sm text-white hover:text-gray-400 font-medium ring-offset-background transition-colors focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 disabled:pointer-events-none disabled:opacity-50",
	{
		variants: {
			variant: {
				simple:
					"bg-secondary relative z-10 bg-transparent hover:border-secondary hover:bg-secondary/50  border border-transparent dark:text-white text-sm md:text-sm transition font-medium duration-200  rounded-md px-4 py-2  flex items-center justify-center",
				default: "bg-primary text-primary-foreground hover:bg-primary/90",
				destructive:
					"bg-destructive text-destructive-foreground hover:bg-destructive/90",
				outline:
					"border border-input bg-background hover:bg-accent hover:text-accent-foreground",
				secondary:
					"bg-secondary text-secondary-foreground hover:bg-secondary/80",
				ghost: "hover:bg-accent hover:text-black hover:stroke-black dark:text-white text-black",
				link: "text-primary underline-offset-4 hover:underline",
			},
			size: {
				default: "h-10 px-4 py-2",
				sm: "h-9 rounded-md px-3",
				lg: "h-11 rounded-md px-8",
				icon: "h-10 w-10",
			},
		},
		defaultVariants: {
			variant: "default",
			size: "default",
		},
	}
);

export interface ButtonProps
	extends React.ButtonHTMLAttributes<HTMLButtonElement>,
		VariantProps<typeof buttonVariants> {
	asChild?: boolean;
}

const Button = React.forwardRef<HTMLButtonElement, ButtonProps>(
	({ className, variant, size, asChild = false, ...props }, ref) => {
		const Comp = asChild ? Slot : "button";
		return (
			<Comp
				className={cn(buttonVariants({ variant, size, className }))}
				ref={ref}
				{...props}
			/>
		);
	}
);
Button.displayName = "Button";

export { Button, buttonVariants };

import { ClassValue, clsx } from "clsx";
import { twMerge } from "tailwind-merge";

export function cn(...inputs: ClassValue[]) {
	return twMerge(clsx(inputs));
}

"use client";

import React from "react";

import { cn } from "@/registry/utilities/cn";
import * as LabelPrimitive from "@radix-ui/react-label";
import { cva, type VariantProps } from "class-variance-authority";

const labelVariants = cva(
	"text-sm font-medium leading-none peer-disabled:cursor-not-allowed peer-disabled:opacity-70"
);

const Label = React.forwardRef<
	React.ElementRef<typeof LabelPrimitive.Root>,
	React.ComponentPropsWithoutRef<typeof LabelPrimitive.Root> &
		VariantProps<typeof labelVariants>
>(({ className, ...props }, ref) => (
	<LabelPrimitive.Root
		ref={ref}
		className={cn(labelVariants(), className)}
		{...props}
	/>
));
Label.displayName = LabelPrimitive.Root.displayName;

export { Label };
